<?php
require_once __DIR__.'/includes/config.php'; require_admin();
$msg='';$error='';
try {
 if($_SERVER['REQUEST_METHOD']==='POST'){
  verify_csrf();$sid=(int)($_POST['student_id']??0);$event=$_POST['event_type']??'';$date=$_POST['event_date']??date('Y-m-d');$notes=trim($_POST['notes']??'');$target=(int)($_POST['to_class_id']??0);
  if(!$sid||!in_array($event,['promoted','transferred','withdrawn','graduated','reactivated'],true))throw new RuntimeException('Select a student and valid lifecycle action.');
  $dbh->beginTransaction();$q=$dbh->prepare('SELECT StudentId,ClassId,Status,StudentName FROM tblstudents WHERE StudentId=? FOR UPDATE');$q->execute([$sid]);$student=$q->fetch();if(!$student)throw new RuntimeException('Student not found.');$from=(int)$student['ClassId'];
  if(in_array($event,['promoted','transferred'],true)){if(!$target)throw new RuntimeException('Choose the destination class.');$c=$dbh->prepare('SELECT id FROM tblclasses WHERE id=?');$c->execute([$target]);if(!$c->fetchColumn())throw new RuntimeException('Destination class does not exist.');$u=$dbh->prepare('UPDATE tblstudents SET ClassId=?,Status=1,UpdationDate=NOW() WHERE StudentId=?');$u->execute([$target,$sid]);}
  elseif(in_array($event,['withdrawn','graduated'],true)){$u=$dbh->prepare('UPDATE tblstudents SET Status=0,UpdationDate=NOW() WHERE StudentId=?');$u->execute([$sid]);}
  else {$u=$dbh->prepare('UPDATE tblstudents SET Status=1,UpdationDate=NOW() WHERE StudentId=?');$u->execute([$sid]);}
  $q=$dbh->prepare('INSERT INTO srms_student_lifecycle(student_id,event_type,from_class_id,to_class_id,event_date,notes,actor_admin_id) VALUES(?,?,?,?,?,?,?)');$q->execute([$sid,$event,$from,$target?:null,$date,$notes?:null,$_SESSION['admin_id']??null]);$dbh->commit();audit_log($dbh,'STUDENT_LIFECYCLE',"{$event} student {$sid}");$msg='Student lifecycle action saved.';
 }
 $students=$dbh->query('SELECT s.StudentId,s.StudentName,s.RollId,s.ClassId,s.Status,c.ClassName,c.Section FROM tblstudents s LEFT JOIN tblclasses c ON c.id=s.ClassId ORDER BY s.StudentName')->fetchAll();$classes=$dbh->query('SELECT id,ClassName,Section FROM tblclasses ORDER BY ClassNameNumeric,Section')->fetchAll();$history=$dbh->query('SELECT l.*,s.StudentName,s.RollId,fc.ClassName from_class,tc.ClassName to_class FROM srms_student_lifecycle l JOIN tblstudents s ON s.StudentId=l.student_id LEFT JOIN tblclasses fc ON fc.id=l.from_class_id LEFT JOIN tblclasses tc ON tc.id=l.to_class_id ORDER BY l.created_at DESC LIMIT 100')->fetchAll();
} catch(Throwable $e){if($dbh->inTransaction())$dbh->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Unable to save lifecycle event. Ensure Phase 12 migration is installed.';if(!($e instanceof RuntimeException))error_log('Lifecycle error: '.$e->getMessage());$students=$students??[];$classes=$classes??[];$history=$history??[];}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student Lifecycle | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"></head><body class="top-navbar-fixed"><div class="main-wrapper"><?php include 'includes/topbar.php';?><div class="content-wrapper"><div class="content-container"><?php include 'includes/leftbar.php';?><main class="main-page"><div class="container-fluid" style="padding:20px"><div style="display:flex;justify-content:space-between;flex-wrap:wrap"><h2>Student Lifecycle</h2><a class="btn btn-default" href="dashboard.php">Dashboard</a></div><?php if($msg):?><div class="alert alert-success"><?=e($msg)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="panel"><div class="panel-heading"><h3>Promotion, transfer, withdrawal and graduation</h3></div><div class="panel-body"><form method="post"><?=csrf_field()?><div class="row"><div class="col-md-4 form-group"><label>Student</label><select name="student_id" class="form-control" required><option value="">Select student</option><?php foreach($students as $s):?><option value="<?=$s['StudentId']?>"><?=e($s['StudentName'].' — '.$s['RollId'].' — '.$s['ClassName'].' '.$s['Section'])?></option><?php endforeach;?></select></div><div class="col-md-3 form-group"><label>Action</label><select name="event_type" id="eventType" class="form-control" required><option value="promoted">Promote</option><option value="transferred">Transfer to class</option><option value="withdrawn">Withdraw</option><option value="graduated">Graduate</option><option value="reactivated">Reactivate</option></select></div><div class="col-md-3 form-group" id="destination"><label>Destination class</label><select name="to_class_id" class="form-control"><option value="">Choose class</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>"><?=e($c['ClassName'].' '.$c['Section'])?></option><?php endforeach;?></select></div><div class="col-md-2 form-group"><label>Effective date</label><input type="date" name="event_date" class="form-control" value="<?=date('Y-m-d')?>" required></div></div><div class="form-group"><label>Reason / notes</label><textarea name="notes" class="form-control" maxlength="500" rows="2"></textarea></div><button class="btn btn-primary">Save lifecycle action</button></form><p class="text-muted" style="margin-top:10px">Every action is recorded in the lifecycle history. Withdrawal and graduation mark the student inactive; historical results and financial records are retained.</p></div></div><div class="panel"><div class="panel-heading"><h3>Recent lifecycle history</h3></div><div class="panel-body table-responsive"><table class="table table-striped"><thead><tr><th>Date</th><th>Student</th><th>Action</th><th>From</th><th>To</th><th>Notes</th></tr></thead><tbody><?php foreach($history as $h):?><tr><td><?=e($h['event_date'])?></td><td><?=e($h['StudentName'].' ('.$h['RollId'].')')?></td><td><?=e(ucfirst($h['event_type']))?></td><td><?=e($h['from_class']??'—')?></td><td><?=e($h['to_class']??'—')?></td><td><?=e($h['notes']??'')?></td></tr><?php endforeach;?><?php if(!$history):?><tr><td colspan="6">No lifecycle actions recorded.</td></tr><?php endif;?></tbody></table></div></div></div><script>document.getElementById('eventType').addEventListener('change',function(){document.getElementById('destination').style.display=['promoted','transferred'].includes(this.value)?'block':'none';});document.getElementById('eventType').dispatchEvent(new Event('change'));</script></body></html>
